 */
public object FfiConverterTypeKeystoreCipher: FfiConverter<KeystoreCipher, Long> {
    internal val handleMap = UniffiHandleMap<KeystoreCipher>()

    override fun lower(value: KeystoreCipher): Long {
        if (value is KeystoreCipherImpl) {
             // Rust-implemented object.  Clone the handle and return it
            return value.uniffiCloneHandle()
         } else {
            // Kotlin object, generate a new vtable handle and return that.
            return handleMap.insert(value)
         }
    }

    override fun lift(value: Long): KeystoreCipher {
        if ((value and 1.toLong()) == 0.toLong()) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
            return KeystoreCipherImpl(UniffiWithHandle, value)
        } else {
            // Kotlin-generated handle, get the object from the handle map
            return handleMap.remove(value)
        }
    }

    override fun read(buf: ByteBuffer): KeystoreCipher {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: KeystoreCipher) = 8UL

    override fun write(value: KeystoreCipher, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}


