public interface MobileVaultInterface {
    
    fun `devices`(): List<DeviceInfo>
    
    /**
     * Sets the vault file aside and forgets the Secret Key file; the app
     * deletes its Keystore keys and bundle on the `removed` event.
     */
    fun `removeDevice`(`confirmation`: kotlin.String)
    
    fun `revokeDevice`(`id`: kotlin.String)
    
    /**
     * Ends the session and locks. The app also deletes its biometric key
     * and bundle (spec §6.4).
     */
    fun `signOut`()
    
    /**
     * The periodic pull while unlocked and in the foreground.
     */
    fun `syncIfDue`()
    
    fun `syncNow`()
    
    /**
     * The user confirmed "Use <login> in <app>?". Stores the binding when
     * online (an item write); offline, fills this once and stores nothing.
     * Never for a browser: a site that does not match is never filled.
     */
    fun `autofillBindAndFill`(`id`: kotlin.String, `target`: TargetFacts): BoundFill
    
    fun `autofillFill`(`id`: kotlin.String, `target`: TargetFacts): FillValues
    
    fun `autofillMatches`(`target`: TargetFacts): List<AutofillMatch>
    
    /**
     * "Search HavenKeys…": any login, by title, username or website. No
     * secrets; filling one goes through `autofill_bind_and_fill`.
     */
    fun `autofillSearch`(`query`: kotlin.String): List<AutofillMatch>
    
    /**
     * Not a secret; answered while locked so the app can pick its UI.
     */
    fun `autofillTargetKind`(`target`: TargetFacts): TargetKind
    
    fun `autofillTotp`(`id`: kotlin.String, `target`: TargetFacts): kotlin.String
    
    fun `confirmBeforeFilling`(): kotlin.Boolean
    
    /**
     * Returns the new item's ID.
     */
    fun `createItem`(`draft`: ItemDraft): kotlin.String
    
    /**
     * The identity cannot be deleted (the core refuses).
     */
    fun `deleteItem`(`id`: kotlin.String)
    
    /**
     * What the editor needs to open `id`: names and presence, the title,
     * websites and username. No secret.
     */
    fun `itemEdit`(`id`: kotlin.String): ItemEdit
    
    /**
     * The editor for a new item of `kind`. The identity cannot be created.
     */
    fun `itemTemplate`(`kind`: ItemKind): ItemEdit
    
    fun `updateItem`(`id`: kotlin.String, `draft`: ItemDraft)
    
    fun `generatePassword`(`o`: GeneratorOptions): Generated
    
    fun `itemView`(`id`: kotlin.String): ItemView
    
    fun `listItems`(): List<ItemSummary>
    
    /**
     * Exactly one field of one item.
     */
    fun `reveal`(`id`: kotlin.String, `key`: kotlin.String): kotlin.String
    
    fun `search`(`query`: kotlin.String): List<ItemSummary>
    
    fun `totp`(`id`: kotlin.String): TotpNow
    
    fun `activate`(`invite`: kotlin.String, `password`: kotlin.String): Status
    
    /**
     * Decode a camera frame. A HavenKeys kit is kept here, in Rust, until
     * `sign_in_with_kit`; the app only learns the address and the server.
     */
    fun `scanKit`(`frame`: LumaFrame): KitPreview?
    
    fun `signIn`(`serverUrl`: kotlin.String, `email`: kotlin.String, `password`: kotlin.String, `secretKey`: kotlin.String): Status
    
    /**
     * The kit stays held after a failure, so a mistyped password can be
     * retried without scanning again.
     */
    fun `signInWithKit`(`password`: kotlin.String): Status
    
    /**
     * After Android's save sheet was confirmed. Online only; not app use,
     * so the idle timer is not touched.
     */
    fun `autofillSave`(`target`: TargetFacts, `login`: SaveLogin): SaveResult
    
    fun `settings`(): MobileSettings
    
    fun `updateSettings`(`s`: MobileSettings)
    
    /**
     * The bytes the app seals with its biometric Keystore key. The app
     * zeroes its copy right after sealing.
     */
    fun `createUnlockBundle`(`password`: kotlin.String, `bootCount`: kotlin.Long): kotlin.ByteArray
    
    /**
     * `secret_key` is the Emergency Kit's key, typed when this device lacks
     * it (`Status::needs_secret_key`); the device keeps it after unlocking.
     */
    fun `unlockPassword`(`password`: kotlin.String, `secretKey`: kotlin.String?): Status
    
    fun `unlockWithBundle`(`bundle`: kotlin.ByteArray, `bootCount`: kotlin.Long): Status
    
    fun `forgetKit`()
    
    fun `lock`()
    
    fun `screenTurnedOff`()
    
    /**
     * Safe while locked: no secrets.
     */
    fun `status`(): Status
    
    /**
     * Check the auto-lock now (the app calls this when it returns to the
     * foreground, in case the process was frozen).
     */
    fun `tick`()
    
    /**
     * The user did something: reset the idle timer. The app calls this for
     * real interaction only; reads never touch (see `items.rs`).
     */
    fun `touch`()
    
    companion object
}

