/**
 * @suppress
 */
public object FfiConverterTypeVaultEvents: FfiConverter<VaultEvents, Long> {
    internal val handleMap = UniffiHandleMap<VaultEvents>()

    override fun lower(value: VaultEvents): Long {
        if (value is VaultEventsImpl) {
             // Rust-implemented object.  Clone the handle and return it
            return value.uniffiCloneHandle()
         } else {
            // Kotlin object, generate a new vtable handle and return that.
            return handleMap.insert(value)
         }
    }

    override fun lift(value: Long): VaultEvents {
        if ((value and 1.toLong()) == 0.toLong()) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
            return VaultEventsImpl(UniffiWithHandle, value)
        } else {
            // Kotlin-generated handle, get the object from the handle map
            return handleMap.remove(value)
        }
    }

    override fun read(buf: ByteBuffer): VaultEvents {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: VaultEvents) = 8UL

    override fun write(value: VaultEvents, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



