sealed class Change {
    
    object Keep : Change()
    
    
    data class Replace(
        val `value`: kotlin.String) : Change()
        
    {
        

        companion object
    }
    
    object Remove : Change()
    
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeChange : FfiConverterRustBuffer<Change>{
    override fun read(buf: ByteBuffer): Change {
        return when(buf.getInt()) {
            1 -> Change.Keep
            2 -> Change.Replace(
                FfiConverterString.read(buf),
                )
            3 -> Change.Remove
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: Change): ULong = when(value) {
        is Change.Keep -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is Change.Replace -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`value`)
            )
        }
        is Change.Remove -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
    }

    override fun write(value: Change, buf: ByteBuffer) {
        when(value) {
            is Change.Keep -> {
                buf.putInt(1)
                Unit
            }
            is Change.Replace -> {
                buf.putInt(2)
                FfiConverterString.write(value.`value`, buf)
                Unit
            }
            is Change.Remove -> {
                buf.putInt(3)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}







